/**
 * @name SallaBulletDeliveryTag
 * @description Fixed "Quick Delivery" tag for the storefront homepage header
 *   (e.g. "توصيل خلال ساعتين" / "Delivery within 2 hours").
 *
 *   Eligibility is decided entirely by the backend and delivered as a single
 *   boolean, `store.shipping.has_bullet_delivery_tag` (Store-Module
 *   `StoreSettingsAction::isQuickDeliveryEligible`). The backend sets it true only
 *   when the store is on Pro, Quick Delivery (`bullet-delivery`) is accessible for
 *   customers, and the request already carries a resolved scope allocation (the
 *   branch resolved during the login-cycle). The flag is recomputed per branch and
 *   re-injected on each page load — including after the login-cycle reload — so the
 *   tag re-evaluates naturally without a client-side eligibility gate.
 *
 *   Read-only: no network request; renders nothing when not eligible (fail-safe —
 *   never a broken/half tag, no layout shift).
 * @tag salla-bullet-delivery-tag
 */
export declare class SallaBulletDeliveryTag {
    /** Mirrors the backend `has_bullet_delivery_tag` flag; drives whether the tag renders. */
    isEligible: boolean;
    componentWillLoad(): Promise<void>;
    /** Fixed tag copy. Localized via lang key when present, otherwise a language-aware default. */
    private getTagLabel;
    render(): any;
}
